/// <summary>
/// DP class for SO Manifest DangerousGoods report
/// </summary>
[SrsReportParameterAttribute(classStr(METCommonReportContract))]
internal final class METSalesDangerousGoodsManifestDP extends SrsReportDataProviderPreProcessTempDB
{
    METSalesDangerousGoodsManifestTmp metSalesDangerousGoodsManifestTmp;
    METSalesDangerousGoodsManifestLineTmp metSalesDangerousGoodsManifestLineTmp;
    RecordInsertList    headerList, lineList;

}

Method.Source:
/// <summary>
/// Get METSalesDangerousGoodsManifestTmp
/// </summary>
/// <returns>METSalesDangerousGoodsManifestTmp</returns>
[SrsReportDataSetAttribute(tableStr(METSalesDangerousGoodsManifestTmp))]
public METSalesDangerousGoodsManifestTmp getMETSalesDangerousGoodsManifestTmp()
{
    select metSalesDangerousGoodsManifestTmp;
    return metSalesDangerousGoodsManifestTmp;
}

/// <summary>
/// Get METSalesDangerousGoodsManifestLineTmp
/// </summary>
/// <returns>METSalesDangerousGoodsManifestLineTmp</returns>
[SrsReportDataSetAttribute(tableStr(METSalesDangerousGoodsManifestLineTmp))]
public METSalesDangerousGoodsManifestLineTmp getMETSalesDangerousGoodsManifestLineTmp()
{
    select metSalesDangerousGoodsManifestLineTmp;
    return metSalesDangerousGoodsManifestLineTmp;
}

/// <summary>
/// Report business logic
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    METCommonReportContract             contract = this.parmDataContract();

    headerList = new RecordInsertList(tableNum(METSalesDangerousGoodsManifestTmp), true, true, true, true, true, metSalesDangerousGoodsManifestTmp);
    lineList = new RecordInsertList(tableNum(METSalesDangerousGoodsManifestLineTmp), true, true, true, true, true, metSalesDangerousGoodsManifestLineTmp);

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId();
    if (metSalesOrderShipmentLoadHeader)
    {
        this.insertHeaderData(metSalesOrderShipmentLoadHeader);

        headerList.insertDatabase();
    }

    while select  ItemId, Quantity, RecId from metSalesOrderShipmentLoadLines
        exists join metSalesOrderShipmentLoadHeader
        where  metSalesOrderShipmentLoadLines.shipmentid == metSalesOrderShipmentLoadHeader.ShipmentId
        && metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId()
    {
        this.insertLineData(metSalesOrderShipmentLoadLines, metSalesOrderShipmentLoadHeader);
    }
    lineList.insertDatabase();
}

/// <summary>
/// Insert into header table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertHeaderData(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    InventLocation inventLocationTo;

    select firstonly inventLocationTo
        where inventLocationTo.InventLocationId == _metSalesOrderShipmentLoadHeader.ToWarehouse;

    METIndustryKeyTable metIndustryKeyTable = METIndustryKeyTable::find(inventLocationTo.METWHSubEntity);

    metSalesDangerousGoodsManifestTmp.MFGLogo = SysDocuBrandImages::getImage(inventLocationTo.METWHSubEntity);
    metSalesDangerousGoodsManifestTmp.CompanyName = metIndustryKeyTable.CompanyName;
    metSalesDangerousGoodsManifestTmp.BranchName = inventLocationTo.Name;
    metSalesDangerousGoodsManifestTmp.BranchAddress = inventLocationTo.address();
    metSalesDangerousGoodsManifestTmp.Route = _metSalesOrderShipmentLoadHeader.Route;
    metSalesDangerousGoodsManifestTmp.RouteStopNum = _metSalesOrderShipmentLoadHeader.RouteStopNum;
    metSalesDangerousGoodsManifestTmp.AnyClass = this.checkClass(_metSalesOrderShipmentLoadHeader);

    CompanyInfo companyInfo;

    select firstonly METDocumentNum, METRevision, METRevisionDate
        from companyInfo
        where companyInfo.DataArea == curExt();

    metSalesDangerousGoodsManifestTmp.DocumentNo = companyInfo.METDocumentNum;
    metSalesDangerousGoodsManifestTmp.Revision = companyInfo.METRevision;
    metSalesDangerousGoodsManifestTmp.RevisionDate = companyInfo.METRevisionDate;

    headerList.add(metSalesDangerousGoodsManifestTmp);
}

/// <summary>
/// Insert into Line data
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadLines">METSalesOrderShipmentLoadLines</param>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertLineData(METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines, METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    metSalesDangerousGoodsManifestLineTmp.SalesOrder = _metSalesOrderShipmentLoadLines.ShipmentId;

    InventTransferTable inventTransferTable;
    InventLocation inventLocationTo;
    METInventLocation metInventLocationTo;
    CustTable custTable;
    HMIMItemMaterial hmimItemMaterial;
    METInventTable metInventTable;

    select firstonly custTable
        exists join metInventLocationTo
        where metInventLocationTo.InternalCustomer == custTable.AccountNum
        exists join inventLocationTo
        where inventLocationTo.RecId == metInventLocationTo.InventLocation
        exists join inventTransferTable
        where inventLocationTo.InventLocationId == inventTransferTable.InventLocationIdTo
        && inventTransferTable.TransferId == _metSalesOrderShipmentLoadLines.OrderNum;

    metSalesDangerousGoodsManifestLineTmp.CustAccount = custTable.AccountNum;
    metSalesDangerousGoodsManifestLineTmp.CustName = custTable.name();
    metSalesDangerousGoodsManifestLineTmp.Stop = _metSalesOrderShipmentLoadHeader.RouteStopNum;
    metSalesDangerousGoodsManifestLineTmp.ItemId = _metSalesOrderShipmentLoadLines.ItemId;
    metSalesDangerousGoodsManifestLineTmp.ItemDesc = InventTable::find(_metSalesOrderShipmentLoadLines.ItemId).itemName();

    select firstonly hmimItemMaterial
        where hmimItemMaterial.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metSalesDangerousGoodsManifestLineTmp.ClassCode = hmimItemMaterial.ClassCode;
    metSalesDangerousGoodsManifestLineTmp.SubRisk = hmimItemMaterial.DivisionCode;
    metSalesDangerousGoodsManifestLineTmp.UN = hmimItemMaterial.IdentificationCode;
    metSalesDangerousGoodsManifestLineTmp.PackingGroupCode = hmimItemMaterial.PackingGroupCode;
    metSalesDangerousGoodsManifestLineTmp.PackType = hmimItemMaterial.PackCode;
    metSalesDangerousGoodsManifestLineTmp.UnitOfMeasure = hmimItemMaterial.UnitOfMeasure;

    select firstonly metInventTable
        where metInventTable.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metSalesDangerousGoodsManifestLineTmp.ItemSize = metInventTable.ItemSize;
    metSalesDangerousGoodsManifestLineTmp.ItemUnit = _metSalesOrderShipmentLoadLines.Quantity * any2Int(metInventTable.ItemSize);
    metSalesDangerousGoodsManifestLineTmp.Hazchem = hmimItemMaterial.LabelCode;

    const str each = 'EA';

    metSalesDangerousGoodsManifestLineTmp.ItemPack = (UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(InventTransferLine::find(_metSalesOrderShipmentLoadLines.InventTransId, _metSalesOrderShipmentLoadLines.LineNum).UnitId).RecId,
                                                UnitOfMeasure::findBySymbol(each).RecId,
                                                EcoResProduct::findByProductNumber(_metSalesOrderShipmentLoadLines.ItemId).RecId).Factor) * _metSalesOrderShipmentLoadLines.Quantity;
    metSalesDangerousGoodsManifestLineTmp.Type = hmimItemMaterial.MaterialDescription;

    lineList.add(metSalesDangerousGoodsManifestLineTmp);
}

/// <summary>
/// This method is used to check if item belongs to a Divison or not
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
/// <returns>boolean</returns>
public boolean checkClass(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines metSalesOrderShipmentLoadLines;
    HMIMItemMaterial hmIMItemMaterial;
    const str twoOne = '2.1';
    const str twoThree = '2.3';
    const str pgOne = 'PG1';

    select firstonly RecId from hmIMItemMaterial
        join metSalesOrderShipmentLoadLines
        where hmIMItemMaterial.ItemId == metSalesOrderShipmentLoadLines.ItemId
        && metSalesOrderShipmentLoadLines.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId
        && ( hmIMItemMaterial.DivisionCode == twoOne || hmIMItemMaterial.DivisionCode == twoThree || hmIMItemMaterial.DivisionCode == pgOne );

    if (hmIMItemMaterial)
    {
        return true;
    }

    return false;
}
